// Item catalog generated by scripts/gen-data.mjs, plus lookups by save-file id.
// Every owned item and catalog entry is identified by a key:
//   u:<unique name>  s:<set item id>  w:<runeword row>  r:<rune code>  b:<base code>:<quality>
import uniques from "../data/uniques.json";
import sets from "../data/sets.json";
import runewords from "../data/runewords.json";
import runes from "../data/runes.json";
import items from "../data/items.json";
import { nameOf, t } from "./i18n";

export { uniques, sets, runewords, runes };

export const uniqueKey = (u) => `u:${u.en}`;
export const setItemKey = (i) => `s:${i.id}`;
export const runewordKey = (w) => `w:${w.id}`;
export const runeKey = (r) => `r:${r.code}`;

const uniqueById = new Map(uniques.flatMap((u) => u.ids.map((id) => [id, u])));
const setItemById = new Map(sets.flatMap((s) => s.items.map((i) => [i.id, i])));
const runeCodes = new Set(runes.map((r) => r.code));
const runewordRows = new Set(runewords.map((w) => w.id));
const runewordByRecipe = new Map(runewords.map((w) => [w.runes.join(), w]));

// Every catalog entry by key, so search can also list what is missing.
// Legacy uniques are not collectible (not in the Chronicle) and only show up when owned.
export const catalog = new Map([
  ...uniques.map((u) => [uniqueKey(u), { kind: "Unique", names: u, legacy: u.legacy }]),
  ...sets.flatMap((s) => s.items.map((i) => [setItemKey(i), { kind: "Set", names: i }])),
  ...runewords.map((w) => [runewordKey(w), { kind: "runewords", names: w }]),
  ...runes.map((r) => [runeKey(r), { kind: "runes", names: r }]),
]);

// Item codes are up to 4 ASCII chars packed little-endian, space padded.
export const codeOfNumber = (n) => String.fromCharCode(n & 255, (n >>> 8) & 255, (n >>> 16) & 255, n >>> 24).trim();

// Key for an item parsed from a save (see wasm/: d2s crate JSON).
export function keyOf(item, code) {
  if (item.runeword_id != null) {
    // Usually the runes.txt row (verified against real RotW saves); some new runewords don't
    // follow it (Cure), so fall back to the runes socketed in it
    const row = (item.runeword_id & 0xfff) - 27;
    if (runewordRows.has(row)) return `w:${row}`;
    const byRecipe = runewordByRecipe.get(item.sockets.map((s) => s && codeOfNumber(s.code)).join());
    if (byRecipe) return runewordKey(byRecipe);
  }
  const fileIndex = item.quality_data?.SetUnique?.file_index;
  if (item.quality === "Unique" && uniqueById.has(fileIndex)) return uniqueKey(uniqueById.get(fileIndex));
  if (item.quality === "Set" && setItemById.has(fileIndex)) return `s:${fileIndex}`;
  if (runeCodes.has(code)) return `r:${code}`;
  return `b:${code}:${item.quality}`;
}

// Display name for any key, catalog or base item.
export function labelOf(key, lang) {
  const entry = catalog.get(key);
  if (entry) return nameOf(entry.names, lang);
  const [, code, quality] = key.split(":");
  const base = nameOf(items[code], lang);
  return quality === "Normal" ? base : `${t(quality, lang)} ${base}`;
}

// All names of a key, for searching in any language.
export function searchTextOf(key) {
  const entry = catalog.get(key);
  const names = entry ? entry.names : items[key.split(":")[1]];
  return names ? `${names.en} ${names.zh} ${names.zh_tw} ${names.ko}`.toLowerCase() : key;
}

export const baseNameOf = (code, lang) => nameOf(items[code], lang);

// Inventory icon URL (public/items, see scripts/gen-images.mjs) for an owned record or { key, code }
export function imageOf({ key, code, gfx }) {
  const own = catalog.get(key)?.names.img;
  if (own) return `/items/${own}.webp`;
  const base = items[code];
  const variant = gfx != null && base.variants ? (gfx % base.variants) + 1 : "";
  return `/items/${base.img}${variant}.webp`;
}
